#!/bin/sh\nset -eu\n\nGATEWAY_URL="${GATEWAY_URL:-http://new-api:3000}"\nCONFIG_DIR="${CONFIG_DIR:-/config}"\nADMIN_USER="${NEW_API_ADMIN_USERNAME:?NEW_API_ADMIN_USERNAME is required}"\nADMIN_PASSWORD="${NEW_API_ADMIN_PASSWORD:?NEW_API_ADMIN_PASSWORD is required}"\n\nwait_ready() {\n  i=0\n  while [ "$i" -lt 60 ]; do\n    if wget -q -O /tmp/status.json "$GATEWAY_URL/api/status"; then\n      grep -q '"success":true' /tmp/status.json 2>/dev/null || grep -q '"success": true' /tmp/status.json 2>/dev/null && return 0\n    fi\n    i=$((i + 1)); sleep 2\n  done\n  return 1\n}\n\njson_escape() { printf "%s" "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'; }\n\nbootstrap() {\n  user_json=$(json_escape "$ADMIN_USER"); pass_json=$(json_escape "$ADMIN_PASSWORD")\n  body="{\"username\":\"$user_json\",\"password\":\"$pass_json\",\"confirmPassword\":\"$pass_json\",\"SelfUseModeEnabled\":true,\"DemoSiteEnabled\":false}"\n  wget -q -O /tmp/gateway-response.json --header='Content-Type: application/json' --post-data="$body" "$GATEWAY_URL/api/setup" || true\n}\n\nlogin() {\n  user_json=$(json_escape "$ADMIN_USER"); pass_json=$(json_escape "$ADMIN_PASSWORD")\n  body="{\"username\":\"$user_json\",\"password\":\"$pass_json\"}"\n  wget -q -O /tmp/login.json --header='Content-Type: application/json' --post-data="$body" "$GATEWAY_URL/api/user/login"\n  grep -q '"success":true' /tmp/login.json 2>/dev/null || grep -q '"success": true' /tmp/login.json 2>/dev/null\n  TOKEN=$(sed -n 's/.*"access_token"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' /tmp/login.json | head -n 1)\n  [ -n "$TOKEN" ]\n}\n\nnara_keys() {\n  # Add future NARA_KEY_2 / NARA_KEY_3 here; no channel changes are required.\n  for name in NARA_KEY_1 NARA_KEY_2 NARA_KEY_3; do\n    eval "value=\${$name-}"\n    [ -n "$value" ] && printf "%s\n" "$value"\n  done\n}\n\ngemini_health() {\n  [ -n "${GEMINI_API_KEY:-}" ] || return 1\n  wget -q -O /tmp/gemini-health.json --header='Accept: application/json' "https://generativelanguage.googleapis.com/v1beta/models?key=$GEMINI_API_KEY"\n}\n\nmain() {\n  wait_ready || { echo "gateway-init: new-api is not healthy" >&2; exit 1; }\n  bootstrap\n  login || { echo "gateway-init: admin login failed" >&2; exit 1; }\n  [ -s "$CONFIG_DIR/channels.json" ] || exit 1\n  [ -s "$CONFIG_DIR/model-mapping.json" ] || exit 1\n  if [ -n "${GEMINI_API_KEY:-}" ]; then\n    if gemini_health; then echo "gateway-init: Gemini health-check PASS"; else echo "gateway-init: Gemini health-check FAIL; skip eligible"; fi\n  fi\n  echo "gateway-init: authenticated and manifests ready"\n}\n\nmain "$@"\n